/* From Uiverse.io by Javierrocadev - Tags: card, svg, hover effect, cardhover  */
.__UIV_SCOPE__ .card {
  width: 250px;
  height: 200px;
  border-radius: 15px;
  background: rgba(105, 13, 197, 0.103);
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .card::before {
  content: "";
  height: 100px;
  width: 100px;
  position: absolute;
  top: -40%;
  left: -20%;
  border-radius: 50%;
  border: 35px solid rgba(255, 255, 255, 0.102);
  transition: all .8s ease;
  filter: blur(.5rem);
}

.__UIV_SCOPE__ .text {
  flex-grow: 1;
  padding: 15px;
  display: flex;
  flex-direction: column;
  color: aliceblue;
  font-weight: 900;
  font-size: 1.2em;
}

.__UIV_SCOPE__ .subtitle {
  font-size: .6em;
  font-weight: 300;
  color: rgba(240, 248, 255, 0.691);
}

.__UIV_SCOPE__ .icons {
  display: flex;
  justify-items: center;
  align-items: center;
  width: 250px;
  border-radius: 0px 0px 15px 15px;
  overflow: hidden;
}

.__UIV_SCOPE__ .btn {
  border: none;
  width: 84px;
  height: 35px;
  background-color: rgba(247, 234, 234, 0.589);
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .svg-icon {
  width: 25px;
  height: 25px;
  stroke: rgb(38, 59, 126);
}

.__UIV_SCOPE__ .btn:hover {
  background-color: rgb(247, 234, 234);
}

.__UIV_SCOPE__ .card:hover::before {
  width: 140px;
  height: 140px;
  top: -30%;
  left: 50%;
  filter: blur(0rem);
}
